          "url": {
            "value": "(function execute() {\n    var tableName = vaInputs.record_table.getValue();\n    var recordId = vaInputs.record_id.getValue();\n    return vaVars.baseUri + vaVars.portalName + \"?id=form&table=\"+ tableName  + \"&sys_id=\" + recordId;\n})()\n",
